export function formatUsd(value: number): string {
  const usd = Math.max(0, value);
  if (usd === 0) return "$0.00";
  if (usd < 0.01) return `$${usd.toFixed(4)}`;
  if (usd < 1) {
    const three = usd.toFixed(3);
    return `$${three.endsWith("0") ? three.slice(0, -1) : three}`;
  }
