assert.equal(t.formatUsd(0), "$0.00");
assert.equal(t.formatUsd(0.0031), "$0.0031");
assert.equal(t.formatUsd(0.25), "$0.25");
assert.equal(t.formatUsd(0.263), "$0.263");
assert.equal(t.formatUsd(5), "$5.00");
assert.equal(t.formatTokens(950), "950");
assert.equal(t.formatTokens(1500), "1.5k");
assert.equal(t.formatTokens(36400), "36k");
assert.equal(t.formatTokens(300000), "300k");
assert.equal(t.formatTokens(1250000), "1.25M");
assert.equal(t.formatTokens(100_000_000), "100M");
assert.equal(t.usageLevel(0.1, 0.25, false), "normal");
assert.equal(t.usageLevel(0.2, 0.25, false), "warn");
assert.equal(t.usageLevel(0.1, 0.25, true), "capped");
assert.equal(t.usageFraction(2, 1), 1);
assert.equal(t.usageFraction(1, 0), 0);
const meta = { id: "a1", role: "assistant", parts: [{ type: "text", text: "hi" }], metadata: { turnUsage: u({ costUsd: 0.05 }) } } as any;
const live = { id: "a2", role: "assistant", parts: [{ type: "data-turn-usage", id: "turn-usage", data: u({ costUsd: 0.2, final: false }) }], metadata: { turnUsage: u({ costUsd: 0.01 }) } } as any;
const user = { id: "u1", role: "user", parts: [{ type: "text", text: "q" }] } as any;
assert.equal(t.messageTurnUsage(meta)?.costUsd, 0.05);
assert.equal(t.messageTurnUsage(live)?.costUsd, 0.2);
assert.equal(t.latestTurnUsage([user, meta])?.messageId, "a1");
assert.equal(t.latestTurnUsage([user, meta, user]), null);
assert.equal(t.latestTurnUsage([user, live])?.usage.costUsd, 0.2);
assert.equal(t.latestTurnUsage([user, meta, { id: "a3", role: "assistant", parts: [] } as any])?.messageId, "a1");
assert.equal(t.messageTurnUsage({ id: "x", role: "assistant", parts: [], metadata: { turnUsage: { bogus: 1 } } } as any), null);
assert.ok(t.isCapNoteText("\n\nStopped: this reply reached its cost limit (about $0.2600 used of $0.25 per message)."));
assert.ok(t.isCapNoteText("Stopped: this reply reached its token limit (1 used)"));
assert.ok(!t.isCapNoteText("The budget stopped: this reply..."));
assert.equal(t.capNoticeText(u({ capped: true, reason: "cost", costUsd: 0.26 })), "Stopped: this turn hit your $0.25 cost limit (used $0.26). Raise it from the bot name ▾.");
assert.equal(t.capNoticeText(u({ capped: true, reason: "tokens", tokens: 312000 })), "Stopped: this turn hit your 300k token limit (used 312k). Raise it from the bot name ▾.");
assert.deepEqual(t.parseCapsInput("0.5", "300k"), { ok: true, caps: { costCapUsd: 0.5, tokenCap: 300000 } });
assert.deepEqual(t.parseCapsInput("$1", "1,000,000"), { ok: true, caps: { costCapUsd: 1, tokenCap: 1000000 } });
assert.deepEqual(t.parseCapsInput("1", "1.5m"), { ok: true, caps: { costCapUsd: 1, tokenCap: 1500000 } });
const bad = t.parseCapsInput("0", "1.5");
assert.ok(!bad.ok && bad.errors.cost && bad.errors.tokens);
const bad2 = t.parseCapsInput("2000", "200m");
assert.ok(!bad2.ok && bad2.errors.cost && bad2.errors.tokens);
const bad3 = t.parseCapsInput("", "abc");
assert.ok(!bad3.ok && bad3.errors.cost && bad3.errors.tokens);
console.log("turn-usage helpers OK");
EOF
